const revokeWhere = `-- name: RevokeWhere :many
SELECT
  g.account_id,
  a.username,
  t.id AS target_id,
  t.name,
  (cardinality(t.tags) > 1)::BOOLEAN AS other_tags
FROM
  grants g
  JOIN target_accounts a ON a.id = g.account_id
  JOIN targets t ON t.id = a.target_id
WHERE
  g.subject_kind = $1::TEXT
  AND g.subject_id = $2::UUID
  AND (
    t.id = ANY ($3::UUID[])
    OR t.tags && $4::TEXT[]
  )
ORDER BY
  t.name,
  a.username
`

type RevokeWhereParams struct {
	SubjectKind string   `json:"subjectKind"`
	SubjectID   string   `json:"subjectId"`
	TargetIds   []string `json:"targetIds"`
	Tags        []string `json:"tags"`
}

type RevokeWhereRow struct {
	AccountID string `json:"accountId"`
	Username  string `json:"username"`
	TargetID  string `json:"targetId"`
	Name      string `json:"name"`
	OtherTags bool   `json:"otherTags"`
}

// One subject's own grants on the servers a batch revoke names, by id or by tag.
func (q *Queries) RevokeWhere(ctx context.Context, arg *RevokeWhereParams) ([]*RevokeWhereRow, error) {
	rows, err := q.db.Query(ctx, revokeWhere,
		arg.SubjectKind,
		arg.SubjectID,
		arg.TargetIds,
		arg.Tags,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*RevokeWhereRow
	for rows.Next() {
		var i RevokeWhereRow
		if err := rows.Scan(
			&i.AccountID,
			&i.Username,
			&i.TargetID,
			&i.Name,
			&i.OtherTags,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const seedTargetAccountsFromToken = `-- name: SeedTargetAccountsFromToken :exec
WITH
  accounts AS (
    INSERT INTO
      target_accounts (workspace_id, target_id, username)
    SELECT DISTINCT
      g.workspace_id,
      $2::UUID,
      g.username
    FROM
      join_token_grants g
    WHERE
      g.token_id = $1
    ON CONFLICT (target_id, username) DO UPDATE
    SET
      username = EXCLUDED.username
    RETURNING
      id,
      username
  )
INSERT INTO
  grants (account_id, user_id, team_id, service_account_id)
SELECT
  a.id,
  g.user_id,
  g.team_id,
  g.service_account_id
FROM
  join_token_grants g
  JOIN accounts a ON a.username = g.username
WHERE
  g.token_id = $1
ON CONFLICT DO NOTHING
`

type SeedTargetAccountsFromTokenParams struct {
	TokenID  string `json:"tokenId"`
	TargetID string `json:"targetId"`
}

// Copies an enroll token's grants onto a fresh target. Runs once, when the daemon is created.
func (q *Queries) SeedTargetAccountsFromToken(ctx context.Context, arg *SeedTargetAccountsFromTokenParams) error {
	_, err := q.db.Exec(ctx, seedTargetAccountsFromToken, arg.TokenID, arg.TargetID)
	return err
}
